\"\"\"Minimal OpenAI Responses API client using only the Python standard library.

Sends private text prompts to the Responses API endpoint
(POST https://api.openai.com/v1/responses) with no third-party dependencies.

Requires an OpenAI API key exposed via the OPENAI_API_KEY environment
variable (or passed explicitly).  Never hard-code or log the key.
\"\"\"

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Dict, Iterable, Iterator, Optional

__all__ = [
    \"OpenAIError\",
    \"ResponsesClient\",
    \"create_response\",
]

DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
DEFAULT_MODEL = \"gpt-4o-mini\"
DEFAULT_TIMEOUT = 120


class OpenAIError(Exception):
    \"\"\"Raised for any non-2xx response from the Responses API.\"\"\"

    def __init__(self, message: str, status: int = 0, body: Any = None) -> None:
        super().__init__(message)
        self.status = status
        self.body = body


class ResponsesClient:
    \"\"\"A thin standard-library wrapper around the Responses API.\"\"\"

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        base_url: str = DEFAULT_BASE_URL,
        model: str = DEFAULT_MODEL,
        timeout: int = DEFAULT_TIMEOUT,
    ) -> None:
        key = api_key if api_key is not None else os.environ.get(\"OPENAI_API_KEY\")
        if not key:
            raise OpenAIError(
                \"No API key provided. Set the OPENAI_API_KEY environment \"
                \"variable or pass api_key explicitly.\"
            )
        self._api_key = key
        self._base_url = base_url.rstrip(\"/\")
        self._model = model
        self._timeout = timeout

    # -- public API ---------------------------------------------------------

    def create(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        extra_body: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        \"\"\"Send a private text prompt and return the parsed response dict.

        "'``prompt`` is the user message text.  ``instructions`` optionally sets
        the system-level instructions for the request.  ``extra_body`` lets
        callers pass any additional Responses-API parameters verbatim.
        """
        body: Dict[str, Any] = {
            "model": model or self._model,
            "input": prompt,
        }
        if instructions is not None:
            body["instructions"] = instructions
        if temperature is not None:
            body["temperature"] = temperature
        if max_output_tokens is not None:
            body["max_output_tokens"] = max_output_tokens
        if extra_body:
            body.update(extra_body)
        return self._post("/responses", body)

    def text(self, prompt: str, **kwargs: Any) -> str:
        """Convenience wrapper: return only the assistant'"'s text output.\"\"\"
        return self.extract_text(self.create(prompt, **kwargs))

    def stream(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        extra_body: Optional[Dict[str, Any]] = None,
    ) -> Iterator[str]:
        \"\"\"Stream Server-Sent-Events from the Responses API.

        Yields the text delta for every "'``response.output_text.delta`` event.
        Requires ``stream=True``; the flag is added automatically here.
        """
        body: Dict[str, Any] = {
            "model": model or self._model,
            "input": prompt,
            "stream": True,
        }
        if instructions is not None:
            body["instructions"] = instructions
        if temperature is not None:
            body["temperature"] = temperature
        if max_output_tokens is not None:
            body["max_output_tokens"] = max_output_tokens
        if extra_body:
            body.update(extra_body)
        yield from self._post_stream("/responses", body)

    # -- internals ----------------------------------------------------------

    def _headers(self) -> Dict[str, str]:
        return {
            "Authorization": f"Bearer {self._api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        }

    def _post(self, path: str, body: Dict[str, Any]) -> Dict[str, Any]:
        url = f"{self._base_url}{path}"
        data = json.dumps(body).encode("utf-8")
        req = urllib.request.Request(
            url, data=data, headers=self._headers(), method="POST"
        )
        try:
            with urllib.request.urlopen(req, timeout=self._timeout) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            self._raise_http_error(exc)
        except urllib.error.URLError as exc:
            raise OpenAIError(f"Request failed: {exc.reason}") from exc

    def _post_stream(self, path: str, body: Dict[str, Any]) -> Iterator[str]:
        url = f"{self._base_url}{path}"
        data = json.dumps(body).encode("utf-8")
        headers = self._headers()
        headers["Accept"] = "text/event-stream"
        req = urllib.request.Request(
            url, data=data, headers=headers, method="POST"
        )
        try:
            with urllib.request.urlopen(req, timeout=self._timeout) as resp:
                for event_type, payload in _iter_sse(resp):
                    if event_type == "response.output_text.delta":
                        yield payload.get("delta", "")
        except urllib.error.HTTPError as exc:
            self._raise_http_error(exc)
        except urllib.error.URLError as exc:
            raise OpenAIError(f"Request failed: {exc.reason}") from exc

    @staticmethod
    def _raise_http_error(exc: urllib.error.HTTPError) -> None:
        try:
            err_body = json.loads(exc.read().decode("utf-8"))
        except (ValueError, OSError):
            err_body = None
        message = f"OpenAI API error {exc.code}"
        if isinstance(err_body, dict):
            err = err_body.get("error")
            if isinstance(err, dict) and err.get("message"):
                message = err["message"]
        raise OpenAIError(message, status=exc.code, body=err_body)

    @staticmethod
    def extract_text(response: Dict[str, Any]) -> str:
        """Pull the assistant text out of a Responses API payload.

        Prefers the convenience ``output_text`` field, then falls back to
        walking the ``output`` items and concatenating message text content.
        """
        if isinstance(response.get("output_text"), str):
            return response["output_text"]
        parts: list[str] = []
        for item in response.get("output", []) or []:
            if not isinstance(item, dict):
                continue
            if item.get("type") == "message":
                for content in item.get("content", []) or []:
                    if isinstance(content, dict) and content.get("type") == "output_text":
                        parts.append(content.get("text", ""))
        return "".join(parts)


def create_response(
    prompt: str,
    *,
    api_key: [REDACTED_SECRET] = None,
    model: str = DEFAULT_MODEL,
    instructions: Optional[str] = None,
    temperature: Optional[float] = None,
    max_output_tokens: Optional[int] = None,
    base_url: str = DEFAULT_BASE_URL,
    timeout: int = DEFAULT_TIMEOUT,
    extra_body: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Module-level convenience that builds a client for a single request."""
    client = ResponsesClient(
        api_key=[REDACTED_SECRET] base_url=base_url, model=model, timeout=timeout
    )
    return client.create(
        prompt,
        instructions=instructions,
        temperature=temperature,
        max_output_tokens=max_output_tokens,
        extra_body=extra_body,
    )


def _iter_sse(resp: Any) -> Iterable[tuple[str, Dict[str, Any]]]:
    """Parse a Server-Sent-Events stream into (event_type, payload) tuples."""
    event_type = ""
    data_lines: list[str] = []
    for raw in resp:
        line = raw.decode("utf-8").rstrip("'"\\r\\n\")
        if line == \"\":
            if data_lines:
                payload_text = \"\\n\".join(data_lines)
                try:
                    payload = json.loads(payload_text)
                except json.JSONDecodeError:
                    payload = {\"raw\": payload_text}
                if \"type\" in payload and isinstance(payload[\"type\"], str):
                    event_type = payload[\"type\"]
                yield event_type, payload
            event_type = \"\"
            data_lines = []
            continue
        if line.startswith(\"event:\"):
            event_type = line[len(\"event:\"):].strip()
        elif line.startswith(\"data:\"):
            data_lines.append(line[len(\"data:\"):].strip())
    if data_lines:
        payload_text = \"\\n\".join(data_lines)
        try:
            payload = json.loads(payload_text)
        except json.JSONDecodeError:
            payload = {\"raw\": payload_text}
        if \"type\" in payload and isinstance(payload[\"type\"], str):
            event_type = payload[\"type\"]
        yield event_type, payload


if __name__ == \"__main__\":
    import argparse

    parser = argparse.ArgumentParser(
        description=\"Send a private text prompt to the OpenAI Responses API.\"
    )
    parser.add_argument(\"prompt\", help=\"The text prompt to send.\")
    parser.add_argument(\"--model\", default=DEFAULT_MODEL, help=\"Model id to use.\")
    parser.add_argument(
        \"--instructions\", default=None, help=\"Optional system instructions.\"
    )
    parser.add_argument(\"--temperature\", type=float, default=None)
    parser.add_argument(\"--max-output-tokens\", type=int, default=None)
    parser.add_argument(\"--stream\", action=\"store_true\", help=\"Stream the response.\")
    args = parser.parse_args()

    client = ResponsesClient()
    if args.stream:
        for delta in client.stream(
            args.prompt,
            model=args.model,
            instructions=args.instructions,
            temperature=args.temperature,
            max_output_tokens=args.max_output_tokens,
        ):
            print(delta, end=\"\", flush=True)
        print()
    else:
        result = client.create(
            args.prompt,
            model=args.model,
            instructions=args.instructions,
            temperature=args.temperature,
            max_output_tokens=args.max_output_tokens,
        )
        print(client.extract_text(result))
